syntax:
template<typename T>
void f(T* p);

// Specialization for a specific type
template<>
void f<int>(int* p);

code_example:
#include <iostream>

template<typename T>
void f(T* p) {
    std::cout << "Generic template for type: " << typeid(T).name() << std::endl;
}

// Specialization for int type
template<>
void f(int* p) {
    std::cout << "Specialized template for int" << std::endl;
}

int main() {
    double d = 3.14;
    f(&d); // Calls generic template with T = double
    int i = 42;
    f(&i); // Calls specialized template for int
    return 0;
}
